import java.util.*;
public class TeacherSessionsTest {
  static Map<String,Object> make(int periods){Map<String,Object> x=new HashMap<>();x.put("classes",List.of(Map.of("name","6/1","shift","morning")));x.put("teachers",List.of(Map.of("name","Lan","maxSessions",12),Map.of("name","Chưa phân công")));x.put("assignments",List.of(Map.of("className","6/1","teacher","Lan","subject","Toán","periods",periods),Map.of("className","6/1","teacher","Lan","subject","Sử","periods",periods)));x.put("events",List.of());return x;}
  public static void main(String[] args){try{new Main.Scheduler(make(3)).run();throw new AssertionError("Too few lessons accepted");}catch(IllegalArgumentException expected){if(!expected.getMessage().contains("4 buổi"))throw expected;}
    Map<String,Object> result=new Main.Scheduler(make(4),ignored->{},true).run();if(!Boolean.TRUE.equals(result.get("ok")))throw new AssertionError(result);Set<String> sessions=new HashSet<>();for(Object item:(List<?>)result.get("schedule")){Map<?,?> row=(Map<?,?>)item;if("Lan".equals(row.get("teacher")))sessions.add(row.get("shift")+":"+row.get("day"));}if(sessions.size()<4||sessions.size()>5)throw new AssertionError("Expected 4–5 sessions, got "+sessions);
    Map<String,Object> external=make(2);external.put("teachers",List.of(Map.of("name","Lan","sessionRule","1")));external.put("assignments",List.of(Map.of("className","6/1","teacher","Lan","subject","Văn","periods",2)));Map<String,Object> externalResult=new Main.Scheduler(external).run();if(!Boolean.TRUE.equals(externalResult.get("ok")))throw new AssertionError(externalResult);Set<String> externalSessions=new HashSet<>();for(Object item:(List<?>)externalResult.get("schedule")){Map<?,?> row=(Map<?,?>)item;if("Lan".equals(row.get("teacher")))externalSessions.add(row.get("shift")+":"+row.get("day"));}if(externalSessions.size()!=1)throw new AssertionError("External teacher must teach exactly one session");
    Map<String,Object> impossible=make(6);impossible.put("teachers",List.of(Map.of("name","Lan","sessionRule","1")));try{new Main.Scheduler(impossible).run();throw new AssertionError("More than 5 periods in one session accepted");}catch(IllegalArgumentException expected){}
    System.out.println("Default 4–5 sessions and one-session teacher exceptions both work.");}
}
